describe('Error Toast Notification', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.clearLocalStorage();
    cy.clearCookies();
  });

  it('should display error toast notification when action fails', () => {
    cy.get('[data-testid="trigger-failure-action"]').click();

    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.get('[data-testid="toast-notification"]').should('have.class', 'error');
    cy.get('[data-testid="toast-message"]').should('contain', 'Action failed');
    cy.get('[data-testid="toast-icon"]').should('be.visible');
  });

  it('should display error toast with correct styling and auto-dismiss after timeout', () => {
    cy.get('[data-testid="trigger-failure-action"]').click();

    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.get('[data-testid="toast-notification"]').should('have.css', 'background-color');
    cy.get('[data-testid="toast-notification"]').should('have.css', 'color');

    cy.get('[data-testid="toast-notification"]').should('have.class', 'error');
    cy.get('[data-testid="toast-notification"]').should('have.class', 'visible');

    cy.get('[data-testid="toast-notification"]', { timeout: 6000 }).should('not.be.visible');
  });

  it('should allow user to manually dismiss error toast notification', () => {
    cy.get('[data-testid="trigger-failure-action"]').click();

    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.get('[data-testid="toast-close-button"]').should('be.visible');
    cy.get('[data-testid="toast-close-button"]').click();

    cy.get('[data-testid="toast-notification"]').should('not.be.visible');
  });

  it('should display multiple error toasts when multiple actions fail', () => {
    cy.get('[data-testid="trigger-failure-action"]').click();
    cy.get('[data-testid="trigger-failure-action"]').click();

    cy.get('[data-testid="toast-notification"]').should('have.length', 2);
    cy.get('[data-testid="toast-notification"]').each(($toast) => {
      cy.wrap($toast).should('have.class', 'error');
      cy.wrap($toast).should('be.visible');
    });
  });

  it('should display error toast with specific error message from API response', () => {
    cy.intercept('POST', '/api/action', {
      statusCode: 400,
      body: { error: 'Invalid input parameters' }
    }).as('failedAction');

    cy.get('[data-testid="trigger-failure-action"]').click();
    cy.wait('@failedAction');

    cy.get('[data-testid="toast-notification"]').should('be.visible');
    cy.get('[data-testid="toast-message"]').should('contain', 'Invalid input parameters');
  });
});
